const body = $json.body ?? $json;
const requested = Number(body.limit ?? 100);
const limit = Math.max(1, Math.min(100, Number.isFinite(requested) ? Math.floor(requested) : 100));
return [{ json: { limit } }];

const response = $json;
const results = Array.isArray(response.results) ? response.results : [];
const text = (value) => typeof value === 'string' ? value : '';
const contacts = results.map((record) => {
  const props = record.properties ?? {};
  const firstName = text(props.firstname);
  const lastName = text(props.lastname);
  return { nativeId: text(record.id), fullName: [firstName, lastName].filter(Boolean).join(' '), firstName, lastName, email: text(props.email), company: text(props.company), phone: text(props.phone), jobTitle: text(props.jobtitle), website: text(props.website) };
}).filter((contact) => contact.nativeId);
return [{ json: { contacts, readAt: new Date().toISOString(), truncated: Boolean(response.paging?.next) } }];
